"""
Parallel runner for AC2 optimization.
Runs multiple candidates in parallel using multiprocessing.
"""
import numpy as np
import multiprocessing as mp
import sys, time, os
sys.path.insert(0, '/home/crv1pi/agent_runs/ac2_plain_s1')
from eval import evaluate_sequence

def run_candidate(args):
    """Run a single optimization candidate."""
    n, seed, method, budget = args
    np.random.seed(seed)

    try:
        if method == 'coord_ascent_mono':
            # Coordinate ascent on monotonic increasing sequence
            # Parameterize as [1, r1, r1*r2, r1*r2*r3, ...] where ri >= 1
            ratios = np.random.uniform(1.05, 3, n-1)
            seq = np.cumprod([0.3 + 0.2*np.random.rand()] + list(ratios))
            seq = seq / seq[-1]  # normalize

            for iteration in range(2000):
                improved = False
                for i in range(len(seq)):
                    old = seq[i]
                    best_local, best_val = evaluate_sequence(seq.tolist()), old
                    for factor in np.concatenate([
                        np.logspace(-3, -1, 20),
                        np.linspace(0.5, 2, 20),
                    ]):
                        seq[i] = max(0, old * factor)
                        # Enforce monotonicity
                        if i > 0 and seq[i] < seq[i-1]:
                            seq[i] = seq[i-1]
                        if i < len(seq)-1 and seq[i] > seq[i+1]:
                            seq[i] = seq[i+1]
                        try:
                            s = evaluate_sequence(seq.tolist())
                            if s > best_local:
                                best_local = s
                                best_val = seq[i]
                        except:
                            seq[i] = best_val
                            continue
                    seq[i] = best_val

                new_score = evaluate_sequence(seq.tolist())
                if new_score <= best_local + 1e-12:
                    break
                best_local = new_score

            return n, seed, best_local, seq.tolist()

        elif method == 'coord_ascent_general':
            # General coordinate ascent (no monotonicity constraint)
            seq = np.random.uniform(0.1, 1, n)
            seq = seq / seq.max()

            for iteration in range(2000):
                for i in range(len(seq)):
                    old = seq[i]
                    best_local, best_val = evaluate_sequence(seq.tolist()), old
                    for factor in np.concatenate([
                        np.logspace(-3, -1, 20),
                        np.linspace(0.1, 3, 20),
                    ]):
                        seq[i] = max(0, old * factor)
                        try:
                            s = evaluate_sequence(seq.tolist())
                            if s > best_local:
                                best_local = s
                                best_val = seq[i]
                        except:
                            seq[i] = best_val
                            continue
                    seq[i] = best_val

                if evaluate_sequence(seq.tolist()) <= best_local + 1e-12:
                    break
                best_local = evaluate_sequence(seq.tolist())

            return n, seed, best_local, seq.tolist()

        elif method == 'shape_param':
            # Optimize parametric shape: a*(x/b + 1)^p
            best_score = 0
            best_params = None
            for a0 in np.linspace(0.1, 1, 10):
                for b0 in np.linspace(0.1, 2, 10):
                    for p0 in np.linspace(0.1, 5, 10):
                        x = np.linspace(0, 1, n)
                        seq = (a0 * ((x/b0 + 1)**p0)).tolist()
                        try:
                            s = evaluate_sequence(seq)
                            if s > best_score:
                                best_score = s
                                best_params = (a0, b0, p0)
                        except:
                            pass
            return n, seed, best_score, (np.linspace(0, 1, n) / 0.5 + 1)**2  # placeholder

    except Exception as e:
        return n, seed, -1, str(e)

def construct_function(seed=42, budget_s=1000, **kwargs):
    t0 = time.time()

    # Define candidates to run in parallel
    candidates = []
    for n in [3, 4, 5, 6, 7, 8, 10]:
        for trial in range(3):
            candidates.append((n, seed + trial*100, 'coord_ascent_mono', budget_s))
            candidates.append((n, seed + trial*100 + 50, 'coord_ascent_general', budget_s))

    # Run with limited parallelism
    n_cores = min(12, len(candidates))
    results = []

    with mp.Pool(n_cores) as pool:
        for result in pool.imap_unordered(run_candidate, candidates):
            n, seed, score, seq = result
            if score > 0 and isinstance(seq, list):
                print(f"n={n}, seed={seed}: score={score:.6f}")
                results.append((score, seq))
            if time.time() - t0 > budget_s - 10:
                break

    results.sort(reverse=True)
    if results:
        best_score, best_seq = results[0]
        print(f"\nBest: score={best_score:.6f}, n={len(best_seq)}")
        return best_seq
    return [0.375, 0.5, 1.0]  # fallback

if __name__ == "__main__":
    seq = construct_function(seed=42, budget_s=900)
    np.save('/home/crv1pi/agent_runs/ac2_plain_s1/run/best.npy', np.array(seq))
    print(f"Score: {evaluate_sequence(seq):.6f}")
    print(f"Sequence: {seq}")
